//! App passwords: the credentials devices sign in with.
//!
//! - Tokens are generated by the server ([`generate_token`]): 25 random characters from
//!   `[A-Za-z0-9]` (about 149 bits), shown in five groups of five. They are handed out exactly
//!   once and stored only as their SHA-256 digest ([`hash_token`]), so a lookup is a single
//!   indexed equality match on `app_passwords.token_hash`.
//! - Every app password has one or more [`Scope`]s. A scope mounts a directory of the owner's
//!   storage (`storage_path`) at a path of the tree the device sees (`mount_path`) with `view`
//!   (read-only) or `full` access. Full access to everything is the single scope
//!   `/` → `/` (`full`). Mount paths are unique and never nested inside each other, so every
//!   client path belongs to at most one mount.

use rand::RngExt as _;
use secrecy::{ExposeSecret, SecretString};
use sqlx::FromRow;

use crate::{
    db::{self, Pool, Tx},
    error::{Error, Result},
    path::RelPath,
    types::{Permission, Username},
};

/// Maximum length of an app password label, in characters.
pub const MAX_LABEL_CHARS: usize = 255;

/// Characters of a generated token.
const TOKEN_ALPHABET: &[u8] = b"ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789";

/// One mount of an app password. See the [module documentation](self).
#[derive(Debug, Clone, PartialEq, Eq)]
pub struct Scope {
    /// Where the mount appears in the client's tree.
    pub mount_path: RelPath,
    /// The directory of the owner's storage it shows.
    pub storage_path: RelPath,
    /// Access level.
    pub permission: Permission,
}

impl Scope {
    /// Full access to the whole storage tree.
    pub fn full_access() -> Self {
        Self {
            mount_path: RelPath::root(),
            storage_path: RelPath::root(),
            permission: Permission::Full,
        }
    }
}

/// Metadata of an app password, never its value.
#[derive(Debug, Clone, PartialEq, Eq)]
pub struct AppPassword {
    /// Id shown by `app-password list`.
    pub id: i64,
    /// Owner.
    pub user_id: i64,
    /// Human-readable name.
    pub label: String,
    /// Creation time, UNIX seconds.
    pub created_at: i64,
    /// Expiry, UNIX seconds; `None` never expires.
    pub expires_at: Option<i64>,
    /// Last successful authentication, UNIX seconds (updated at most every few minutes).
    pub last_used_at: Option<i64>,
    /// Mounts, ordered by mount path.
    pub scopes: Vec<Scope>,
}

/// A successfully authenticated app password.
#[derive(Debug, Clone, PartialEq, Eq)]
pub struct Device {
    /// The app password's id.
    pub app_password_id: i64,
    /// Owner's id.
    pub user_id: i64,
    /// Owner's name.
    pub username: Username,
    /// Owner's display name.
    pub display_name: String,
    /// Mounts, ordered by mount path.
    pub scopes: Vec<Scope>,
    /// Last recorded use, UNIX seconds.
    pub last_used_at: Option<i64>,
}

/// Generates a new app password token, for example `Ab3dE-fGh1j-KlMn0-pQrSt-Uv9Wx`.
///
/// Used for app passwords that a person may have to type (CLI, admin UI).
pub fn generate_token() -> SecretString {
    grouped_token(5)
}

/// Generates the token of an app password that is handed to a device directly (Login Flow
/// v2): eight groups of five characters (about 238 bits). Nobody types these, so they can be
/// longer than [`generate_token`]'s.
pub fn generate_device_token() -> SecretString {
    grouped_token(8)
}

/// `groups` groups of five random characters, separated by `-`.
fn grouped_token(groups: usize) -> SecretString {
    let mut rng = rand::rng();
    let mut token = String::with_capacity(groups * 6);
    for index in 0..groups * 5 {
        if index > 0 && index % 5 == 0 {
            token.push('-');
        }
        let pick = rng.random_range(0..TOKEN_ALPHABET.len());
        token.push(char::from(TOKEN_ALPHABET[pick]));
    }
    SecretString::from(token)
}

/// SHA-256 digest of a token, the value stored in `app_passwords.token_hash`.
pub fn hash_token(token: &str) -> [u8; 32] {
    crate::secret::digest(token)
}

/// Validates a label.
pub fn check_label(label: &str) -> Result<String> {
    let label = label.trim();
    if label.is_empty() {
        return Err(Error::InvalidLabel("must not be empty"));
    }
    if label.chars().count() > MAX_LABEL_CHARS {
        return Err(Error::InvalidLabel("must be at most 255 characters long"));
    }
    if label.chars().any(char::is_control) {
        return Err(Error::InvalidLabel("must not contain control characters"));
    }
    Ok(label.to_owned())
}

/// Checks that mount paths are unique and not nested. An empty list means full access.
pub fn check_scopes(scopes: Vec<Scope>) -> Result<Vec<Scope>> {
    if scopes.is_empty() {
        return Ok(vec![Scope::full_access()]);
    }
    for (index, scope) in scopes.iter().enumerate() {
        for other in &scopes[index + 1..] {
            if scope.mount_path.starts_with(&other.mount_path)
                || other.mount_path.starts_with(&scope.mount_path)
            {
                return Err(Error::InvalidScopes(format!(
                    "mount paths {} and {} overlap; mounts must not be nested",
                    scope.mount_path, other.mount_path
                )));
            }
        }
    }
    let mut scopes = scopes;
    scopes.sort_by(|a, b| a.mount_path.cmp(&b.mount_path));
    Ok(scopes)
}

/// Creates an app password for `user_id` and returns its id and its value.
///
/// The value is returned exactly once; only its hash is stored. `scopes` is validated with
/// [`check_scopes`] (empty means full access).
pub async fn create(
    pool: &Pool,
    user_id: i64,
    label: &str,
    scopes: Vec<Scope>,
    expires_at: Option<i64>,
) -> Result<(i64, SecretString)> {
    let label = check_label(label)?;
    let scopes = check_scopes(scopes)?;
    let token = generate_token();
    let mut tx = db::begin_immediate(pool).await?;
    let id = insert(&mut tx, user_id, &label, &scopes, expires_at, &token).await?;
    tx.commit().await?;
    Ok((id, token))
}

/// Inserts an app password with the given token inside an open transaction and returns its
/// id. `label` and `scopes` must have passed [`check_label`] and [`check_scopes`].
pub(crate) async fn insert(
    tx: &mut Tx,
    user_id: i64,
    label: &str,
    scopes: &[Scope],
    expires_at: Option<i64>,
    token: &SecretString,
) -> Result<i64> {
    let hash = hash_token(token.expose_secret());
    let id: i64 = sqlx::query_scalar(
        "INSERT INTO app_passwords (user_id, token_hash, label, created_at, expires_at) \
         VALUES (?1, ?2, ?3, ?4, ?5) RETURNING id",
    )
    .bind(user_id)
    .bind(&hash[..])
    .bind(label)
    .bind(db::unix_now())
    .bind(expires_at)
    .fetch_one(&mut **tx)
    .await?;
    for scope in scopes {
        sqlx::query(
            "INSERT INTO app_password_scopes (app_password_id, mount_path, storage_path, \
             permission) VALUES (?1, ?2, ?3, ?4)",
        )
        .bind(id)
        .bind(scope.mount_path.as_str())
        .bind(scope.storage_path.as_str())
        .bind(scope.permission.as_str())
        .execute(&mut **tx)
        .await?;
    }
    Ok(id)
}

#[derive(FromRow)]
struct AppPasswordRow {
    id: i64,
    user_id: i64,
    label: String,
    created_at: i64,
    expires_at: Option<i64>,
    last_used_at: Option<i64>,
}

#[derive(FromRow)]
struct ScopeRow {
    app_password_id: i64,
    mount_path: String,
    storage_path: String,
    permission: String,
}

impl TryFrom<ScopeRow> for Scope {
    type Error = Error;

    fn try_from(row: ScopeRow) -> Result<Self> {
        Ok(Self {
            mount_path: RelPath::from_db(row.mount_path),
            storage_path: RelPath::from_db(row.storage_path),
            permission: row.permission.parse()?,
        })
    }
}

/// Lists the app passwords of a user, oldest first.
pub async fn list(pool: &Pool, user_id: i64) -> Result<Vec<AppPassword>> {
    let rows: Vec<AppPasswordRow> = sqlx::query_as(
        "SELECT id, user_id, label, created_at, expires_at, last_used_at FROM app_passwords \
         WHERE user_id = ?1 ORDER BY id",
    )
    .bind(user_id)
    .fetch_all(pool)
    .await?;
    let scope_rows: Vec<ScopeRow> = sqlx::query_as(
        "SELECT s.app_password_id, s.mount_path, s.storage_path, s.permission \
         FROM app_password_scopes s JOIN app_passwords a ON a.id = s.app_password_id \
         WHERE a.user_id = ?1 ORDER BY s.app_password_id, s.mount_path",
    )
    .bind(user_id)
    .fetch_all(pool)
    .await?;

    let mut passwords: Vec<AppPassword> = rows
        .into_iter()
        .map(|row| AppPassword {
            id: row.id,
            user_id: row.user_id,
            label: row.label,
            created_at: row.created_at,
            expires_at: row.expires_at,
            last_used_at: row.last_used_at,
            scopes: Vec::new(),
        })
        .collect();
    for row in scope_rows {
        if let Some(password) = passwords.iter_mut().find(|p| p.id == row.app_password_id) {
            password.scopes.push(row.try_into()?);
        }
    }
    Ok(passwords)
}

/// Revokes an app password of `user_id`. Returns `false` if there is no such app password.
pub async fn delete(pool: &Pool, user_id: i64, id: i64) -> Result<bool> {
    let mut tx = db::begin_immediate(pool).await?;
    let result = sqlx::query("DELETE FROM app_passwords WHERE id = ?1 AND user_id = ?2")
        .bind(id)
        .bind(user_id)
        .execute(&mut *tx)
        .await?;
    tx.commit().await?;
    Ok(result.rows_affected() == 1)
}

#[derive(FromRow)]
struct DeviceRow {
    id: i64,
    user_id: i64,
    expires_at: Option<i64>,
    last_used_at: Option<i64>,
    username: String,
    display_name: String,
    enabled: bool,
}

/// Checks `username` and an app password.
///
/// Looks the single row with the token's hash up and accepts it only if it belongs to
/// `username`, has not expired at `now`, and the account is enabled. Returns `None` for every
/// kind of mismatch so callers cannot tell them apart.
pub async fn authenticate(
    pool: &Pool,
    username: &str,
    token: &SecretString,
    now: i64,
) -> Result<Option<Device>> {
    let hash = hash_token(token.expose_secret());
    let row: Option<DeviceRow> = sqlx::query_as(sqlx::AssertSqlSafe(format!(
        "{DEVICE_QUERY} WHERE a.token_hash = ?1"
    )))
    .bind(&hash[..])
    .fetch_optional(pool)
    .await?;
    match row {
        Some(row) if row.username == username => device_from_row(pool, row, now).await,
        _ => Ok(None),
    }
}

/// App password `id` as a [`Device`], if it can still authenticate at `now` (see
/// [`is_active`]). For requests that carry another credential tied to an app password, such as
/// a direct download link.
pub async fn device(pool: &Pool, id: i64, now: i64) -> Result<Option<Device>> {
    let row: Option<DeviceRow> = sqlx::query_as(sqlx::AssertSqlSafe(format!(
        "{DEVICE_QUERY} WHERE a.id = ?1"
    )))
    .bind(id)
    .fetch_optional(pool)
    .await?;
    match row {
        Some(row) => device_from_row(pool, row, now).await,
        None => Ok(None),
    }
}

/// The columns of [`DeviceRow`].
const DEVICE_QUERY: &str = "SELECT a.id, a.user_id, a.expires_at, a.last_used_at, u.username, \
     u.display_name, u.enabled FROM app_passwords a JOIN users u ON u.id = a.user_id";

/// The device of `row` with its scopes, unless the account is disabled or the app password
/// expired at `now`.
async fn device_from_row(pool: &Pool, row: DeviceRow, now: i64) -> Result<Option<Device>> {
    if !row.enabled || row.expires_at.is_some_and(|at| at <= now) {
        return Ok(None);
    }

    let scopes: Vec<ScopeRow> = sqlx::query_as(
        "SELECT app_password_id, mount_path, storage_path, permission \
         FROM app_password_scopes WHERE app_password_id = ?1 ORDER BY mount_path",
    )
    .bind(row.id)
    .fetch_all(pool)
    .await?;
    Ok(Some(Device {
        app_password_id: row.id,
        user_id: row.user_id,
        username: Username::new(row.username)?,
        display_name: row.display_name,
        scopes: scopes
            .into_iter()
            .map(Scope::try_from)
            .collect::<Result<_>>()?,
        last_used_at: row.last_used_at,
    }))
}

/// Whether app password `id` can still authenticate at `now`: it exists, has not expired, and
/// its account is enabled. Long-lived connections (notify_push) check this periodically, so
/// revoking an app password or disabling an account also ends them.
pub async fn is_active(pool: &Pool, id: i64, now: i64) -> Result<bool> {
    let active: Option<i64> = sqlx::query_scalar(
        "SELECT 1 FROM app_passwords a JOIN users u ON u.id = a.user_id \
         WHERE a.id = ?1 AND u.enabled = 1 AND (a.expires_at IS NULL OR a.expires_at > ?2)",
    )
    .bind(id)
    .bind(now)
    .fetch_optional(pool)
    .await?;
    Ok(active.is_some())
}

/// Records that an app password was used at `now`.
///
/// Callers throttle this (see the server's authenticator); the statement itself only writes
/// when the stored value is older than `now`.
pub async fn record_use(pool: &Pool, id: i64, now: i64) -> Result<()> {
    sqlx::query(
        "UPDATE app_passwords SET last_used_at = ?2 \
         WHERE id = ?1 AND (last_used_at IS NULL OR last_used_at < ?2)",
    )
    .bind(id)
    .bind(now)
    .execute(pool)
    .await?;
    Ok(())
}

#[cfg(test)]
mod tests {
    use super::*;

    fn scope(mount: &str, storage: &str, permission: Permission) -> Scope {
        Scope {
            mount_path: RelPath::parse(mount).unwrap(),
            storage_path: RelPath::parse(storage).unwrap(),
            permission,
        }
    }

    #[test]
    fn tokens_are_random_grouped_alphanumerics() {
        let first = generate_token();
        let second = generate_token();
        let value = first.expose_secret();
        assert_eq!(value.len(), 29);
        let groups: Vec<&str> = value.split('-').collect();
        assert_eq!(groups.len(), 5);
        assert!(
            groups
                .iter()
                .all(|g| g.len() == 5 && g.bytes().all(|b| b.is_ascii_alphanumeric()))
        );
        assert_ne!(value, second.expose_secret());
    }

    #[test]
    fn hashes_are_sha256() {
        assert_eq!(
            hash_token("abc")[..4],
            [0xba, 0x78, 0x16, 0xbf],
            "SHA-256 test vector"
        );
    }

    #[test]
    fn empty_scopes_mean_full_access() {
        assert_eq!(check_scopes(Vec::new()).unwrap(), [Scope::full_access()]);
    }

    #[test]
    fn nested_or_duplicate_mounts_are_rejected() {
        let ok = check_scopes(vec![
            scope("/b", "/x", Permission::Full),
            scope("/a", "/x", Permission::View),
        ])
        .unwrap();
        assert_eq!(ok[0].mount_path.as_str(), "a", "sorted by mount path");

        for bad in [
            vec![
                scope("/", "/", Permission::View),
                scope("/a", "/a", Permission::Full),
            ],
            vec![
                scope("/a", "/x", Permission::View),
                scope("/a/b", "/y", Permission::Full),
            ],
            vec![
                scope("/a", "/x", Permission::View),
                scope("/a", "/y", Permission::Full),
            ],
        ] {
            assert!(check_scopes(bad).is_err());
        }
        // Prefixes are compared per segment.
        assert!(
            check_scopes(vec![
                scope("/a", "/x", Permission::View),
                scope("/ab", "/y", Permission::Full),
            ])
            .is_ok()
        );
    }

    #[test]
    fn labels_are_validated() {
        assert_eq!(check_label("  phone ").unwrap(), "phone");
        assert!(check_label("").is_err());
        assert!(check_label("a\nb").is_err());
        assert!(check_label(&"x".repeat(256)).is_err());
    }
}
